"use client";

import { useParams } from "next/navigation";
import Image from "next/image";
import { useState } from "react";
import { useSelector } from "react-redux";
import { RootState } from "@/redux/store";
import { FaStar, FaRegStar } from "react-icons/fa";
import UserProductCard from "@/component/userProductCard";

export default function ProductViewPage() {
  const params = useParams();
  const id = params.id;

  const { allProductsData } = useSelector(
    (state: RootState) => state.vendor
  );

  const [activeImage, setActiveImage] = useState(0);

  // ✅ DIRECT FIND (NO useMemo)
  const product = allProductsData?.find(
    (p) => String(p._id) === String(id)
  );

  // ✅ Loading
  if (!allProductsData || allProductsData.length === 0) {
    return (
      <div className="min-h-screen flex items-center justify-center text-white bg-black">
        <h1 className="text-xl">Loading products...</h1>
      </div>
    );
  }

  // ✅ Not Found
  if (!product) {
    return (
      <div className="min-h-screen flex items-center justify-center text-white bg-black">
        <h1 className="text-xl">❌ Product Not Found</h1>
      </div>
    );
  }

  const images = [
    product.image1,
    product.image2,
    product.image3,
    product.image4,
  ].filter(Boolean);

  // ✅ DEMO RATING (later API se aayega)
  const rating = 4;
  const totalReviews =  124;

  // ✅ RELATED PRODUCTS (CATEGORY ke basis par)
  const relatedProducts = allProductsData?.filter(
    (p) => p?.category === product?.category && p._id !== product._id
  );

  return (
    <div className="min-h-screen bg-gradient-to-br from-black via-gray-900 to-black text-white px-4 py-10">
      <div className="max-w-6xl mx-auto">

        {/* ================== ✅ TOP SECTION (LEFT + RIGHT) ================== */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">

          {/* ✅ LEFT: IMAGE GALLERY */}
          <div className="flex flex-col md:flex-col lg:flex-row gap-4">

            {/* ✅ MAIN IMAGE BOX */}
            <div className="relative w-full lg:w-[450px] h-[420px] bg-black rounded-lg overflow-hidden flex items-center justify-center border border-white/10">
              <Image
                src={images[activeImage]}
                alt={product.title}
                fill
                className="object-contain"
                priority
              />
            </div>

            {/* ✅ THUMBNAILS */}
            <div className="flex flex-row lg:flex-col gap-3 justify-center">
              {images.map((img, i) => (
                <div
                  key={i}
                  onClick={() => setActiveImage(i)}
                  className={`relative w-20 h-20 border rounded cursor-pointer overflow-hidden flex items-center justify-center ${
                    activeImage === i
                      ? "border-blue-600"
                      : "border-white/20"
                  }`}
                >
                  <Image
                    src={img}
                    alt={product.title}
                    fill
                    className="object-contain"
                  />
                </div>
              ))}
            </div>
          </div>

          {/* ✅ RIGHT: BASIC PRODUCT INFO */}
          <div>
            <h1 className="text-3xl font-bold mb-3">{product.title}</h1>
            <p className="text-gray-400 mb-2">{product.category}</p>

            <p className="text-2xl text-green-500 font-bold">
              ₹ {product.price}
            </p>

            {/* ✅ ✅ RATING BELOW PRICE */}
            <div className="flex items-center gap-2 mt-1 mb-4">
              <div className="flex text-yellow-400">
                {[1, 2, 3, 4, 5].map((i) =>
                  i <= rating ? (
                    <FaStar key={i} />
                  ) : (
                    <FaRegStar key={i} />
                  )
                )}
              </div>
              <span className="text-sm text-gray-400">
                ({totalReviews} reviews)
              </span>
            </div>

            <p className="mb-4 text-gray-300">{product.description}</p>

            {/* ✅ STOCK */}
            <p className="mb-3">
              Stock:{" "}
              <span
                className={
                  product.stock > 0
                    ? "text-green-400"
                    : "text-red-400"
                }
              >
                {product.stock > 0 ? "In Stock" : "Out of Stock"}
              </span>
            </p>

            {/* ✅ BUTTON */}
            <button className="w-full bg-blue-600 hover:bg-blue-700 py-3 rounded font-semibold transition">
              Add to Cart
            </button>
          </div>
        </div>

        {/* ================== ✅ BOTTOM SECTION (OTHER DETAILS) ================== */}
        <div className="mt-10 bg-white/5 border border-white/10 rounded-lg p-6">

          {/* ✅ WEARABLE SIZES */}
          {product.isWearable === true &&
            Array.isArray(product.sizes) &&
            product.sizes.length > 0 && (
              <div className="mb-5">
                <p className="font-semibold mb-2">Available Sizes</p>
                <div className="flex flex-wrap gap-2">
                  {product.sizes.map((s: string) => (
                    <span
                      key={s}
                      className="px-3 py-1 border border-white/20 rounded"
                    >
                      {s}
                    </span>
                  ))}
                </div>
              </div>
            )}

          {/* ✅ POLICIES */}
          <div className="space-y-2 mb-6">
            {typeof product.replacementDays === "number" &&
              product.replacementDays > 0 && (
                <p>✅ {product.replacementDays} Days Replacement</p>
              )}

            {product.freeDelivery === true && (
              <p>✅ Free Delivery</p>
            )}

            {product.payOnDelivery === true && (
              <p>✅ Cash on Delivery Available</p>
            )}

            {product.warranty &&
              product.warranty !== "No Warranty" && (
                <p>✅ Warranty: {product.warranty}</p>
              )}
          </div>

          {/* ✅ DETAIL POINTS */}
          {Array.isArray(product.detailsPoints) &&
            product.detailsPoints.length > 0 && (
              <div className="mb-6">
                <p className="font-semibold mb-2">Highlights</p>
                <ul className="list-disc pl-5 space-y-1 text-gray-300">
                  {product.detailsPoints.map((p: string, i: number) => (
                    <li key={i}>{p}</li>
                  ))}
                </ul>
              </div>
            )}
        </div>

        {/* ================== ✅ RELATED PRODUCTS ================== */}
        {/* ================== ✅ RELATED PRODUCTS ================== */}
{Array.isArray(relatedProducts) && relatedProducts.length > 0 && (
  <div className="mt-12">
    <h2 className="text-2xl font-bold mb-5">
      Related Products
    </h2>

    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-5">
      {relatedProducts.slice(0, 8).map((rp) => (
        <UserProductCar       // ✅ REQUIRED KEY
          product={rp}      // ✅ PASSING FULL PRODUCT
        />
      ))}
    </div>
  </div>
)}


      </div>
    </div>
  );
}
